<template><section class="scr-panel" aria-labelledby="scr-chaos-title"><h2 id="scr-chaos-title" class="scr-sr-only">{{ t('nav.chaos') }}</h2><ChaosActions /><label class="scr-range"><span>{{ t('chaos.intensity') }}</span><output>{{ settings.chaos }}%</output><input type="range" min="0" max="100" step="1" :value="settings.chaos" :disabled="core.busy" @change="setChaos" /></label><StatusBanner v-if="settings.seedMode === 'fixed'" tone="warning">{{ t('status.fixedSeed') }}</StatusBanner><StatusBanner v-if="(locks.summary?.locked || 0) > 0" tone="warning">{{ t('status.locks', { count: locks.summary.locked }) }}</StatusBanner><ChaosProgress /><LockControls /><ChaosAdvanced /><ChaosResult /></section></template>
<script setup>
import { useStores } from "../../stores"; import ChaosActions from "./ChaosActions.vue"; import ChaosProgress from "./ChaosProgress.vue"; import ChaosResult from "./ChaosResult.vue"; import ChaosAdvanced from "./ChaosAdvanced.vue"; import LockControls from "./LockControls.vue"; import StatusBanner from "../common/StatusBanner.vue"
const stores = useStores(); const core = stores.core.state; const settings = stores.settings.state; const locks = stores.chaos.state.locks; const { t } = stores.i18n
const setChaos = event => stores.command.send("updateSettings", [{ chaos: Number(event.target.value) }])
</script>
